function caseState(id,address,operation,preview){return{id,address,operation,propertyId:id==='roma'?'property-roma-A12':id==='verdi'?'property-verdi-V03':'property-case-'+id,lifecycle:{status:'open',soldAt:null,deadline:null,closedAt:null},agent:'Giulia Neri',active:false,activatedAt:null,checklist:{ape:{status:'da richiedere',assignee:'agent'},plan:{status:'da richiedere',assignee:'seller'},dico:{status:'da richiedere',assignee:'seller'},manual:{status:'da richiedere',assignee:'seller'}},docs:[],requests:[],dossier:null,gift:{status:'draft',email:'',items:[],memory:[],acceptedAt:null,acceptedItems:[]},preview,history:[]};}
